Console.WriteLine(new List<List<string>>(){(await File.ReadAllLinesAsync("data.txt")).Select(t => t.Trim()).ToList()}.Select(l => (l[..l.IndexOf("")],l[(l.IndexOf("")+1)..])).Select(t => (t.Item1.Select(r => r.Split("-")).Select(r => (long.Parse(r[0]), long.Parse(r[1]))),t.Item2.Select(id => long.Parse(id)))).Sum(l => l.Item2.Count(x => l.Item1.Any(r => r.Item1<=x && x <= r.Item2))));